function validStamp(by,at){return (by===''&&at==='')||(OWNERS.slice(0,3).includes(by)&&typeof at==='string'&&/^\d{4}-\d\d-\d\dT/.test(at)&&Number.isFinite(Date.parse(at)))}
function validateMeeting(m){if(!m||typeof m.label!=='string'||!m.label.trim()||m.label.length>120||typeof m.title!=='string'||!m.title.trim()||m.title.length>180||typeof m.body!=='string'||m.body.length>30000||!validStamp(m.editedBy,m.editedAt))throw Error('Invalid meeting notes.');return m}
function validateActivity(a){if(!Array.isArray(a)||a.length>500)throw Error('Invalid edit history.');for(const e of a){if(!e||typeof e.id!=='string'||!validStamp(e.actor,e.at)||!e.actor||typeof e.message!=='string'||e.message.length>1000||!Array.isArray(e.targets)||e.targets.some(t=>!t||typeof t.id!=='string'||typeof t.title!=='string'||t.title.length>300))throw Error('Invalid edit history entry.')}return a}
