function logChanges(before,message,subject){const at=new Date().toISOString(),targets=[];for(const t of tasks){const old=before.tasks.find(x=>x.id===t.id);if(!old||taskContent(t)!==taskContent(old)||t.id===subject){t.editedBy=actor;t.editedAt=at;targets.push({id:t.id,title:t.title})}}for(const old of before.tasks){if(!tasks.some(t=>t.id===old.id))targets.push({id:old.id,title:old.title})}if(JSON.stringify(before.meeting)!==JSON.stringify(meeting)){meeting.editedBy=actor;meeting.editedAt=at;targets.push({id:'meeting',title:meeting.title})}activity.push({id:crypto.randomUUID(),actor,at,message:message||'Workspace updated',targets});activity=activity.slice(-500)}
