function validate(data){if(!Array.isArray(data)||data.length>2000)throw Error('The backup must contain a task list (up to 2,000 tasks).');const ids=new Set();for(const t of data){if(!t||typeof t.id!=='string'||!/^[a-zA-Z0-9_-]{1,100}$/.test(t.id)||ids.has(t.id))throw Error('Invalid or duplicate task ID.');ids.add(t.id);for(const key of ['title','project','next','notes','source','start','end','dependency'])if(typeof t[key]!=='string'||t[key].length>20000)throw Error('Invalid task field: '+key);if((t.editedBy!==undefined||t.editedAt!==undefined)&&!validStamp(t.editedBy,t.editedAt))throw Error('Invalid edit attribution.');if(!t.title.trim()||!t.project.trim()||!OWNERS.includes(t.owner)||!STATUSES.includes(t.status)||![1,2,3].includes(t.priority)||!['Proposed','Confirmed'].includes(t.dateKind)||typeof t.review!=='boolean')throw Error('Invalid task properties.');if(!validDate(t.start)||!validDate(t.end)||(t.start&&t.end&&t.end<t.start))throw Error('Invalid task dates.');if(!Array.isArray(t.checklist)||t.checklist.length>200||t.checklist.some(c=>!c||typeof c.text!=='string'||c.text.length>20000||typeof c.done!=='boolean'))throw Error('Invalid checklist.');}for(const t of data){if(t.dependency&&!ids.has(t.dependency))throw Error('A dependency is missing.');let seen=new Set([t.id]),p=t;while(p.dependency){if(seen.has(p.dependency))throw Error('Dependencies contain a cycle.');seen.add(p.dependency);p=data.find(x=>x.id===p.dependency);}}return data;}
