function renderTeam(list){$('#workspace').innerHTML=`<div class="team-grid">${OWNERS.filter(o=>o!=='Unassigned'||list.some(t=>t.owner===o)).map(o=>{const ts=list.filter(t=>t.owner===o),active=ts.filter(t=>t.status!=='Done'),doing=ts.filter(t=>t.status==='In progress');return `<section class="team-panel"><div class="team-head">${avatar(o)}<div><h2>${o}</h2><p>${active.length} open · ${doing.length} in progress · ${active.filter(t=>t.priority===1).length} first focus</p></div></div><div class="load-bar"><span style="width:${ts.length?100*doing.length/ts.length:0}%"></span></div>${ts.length?ts.map(card).join(''):'<div class="empty-column">No tasks in this view.</div>'}</section>`}).join('')}</div>`}
function renderTimeline(list){const scheduled=list.filter(t=>t.start&&t.end),unscheduled=list.filter(t=>!t.start||!t.end),end=addDays(rangeStart,rangeDays-1);const todayX=daysBetween(rangeStart,today())/rangeDays*100;$('#workspace').innerHTML=`<div class="timeline-controls"><strong>${fmt(rangeStart)} — ${fmt(end)} ${end.slice(0,4)}</strong><button data-range="prev" aria-label="Previous period">←</button><button data-range="today">Today</button><button data-range="next" aria-label="Next period">→</button><select id="zoom" aria-label="Timeline range"><option value="21" ${rangeDays===21?'selected':''}>3 weeks</option><option value="42" ${rangeDays===42?'selected':''}>6 weeks</option><option value="84" ${rangeDays===84?'selected':''}>12 weeks</option></select></div><div class="timeline-scroll"><div class="timeline-inner"><div class="timeline-header"><div class="timeline-label">PROJECT / TASK</div><div class="timeline-days">${Array.from({length:rangeDays},(_,i)=>{const d=addDays(rangeStart,i),show=rangeDays<=42||i%7===0;return `<span>${show&&i%7===0?new Date(d+'T12:00:00Z').toLocaleDateString('en-AU',{month:'short',timeZone:'UTC'}):'&nbsp;'}<b>${show?+d.slice(-2):'·'}</b></span>`}).join('')}</div></div>${scheduled.map(t=>{const a=daysBetween(rangeStart,t.start),b=daysBetween(rangeStart,t.end)+1,visible=b>0&&a<rangeDays,l=Math.max(0,a)/rangeDays*100,w=(Math.min(rangeDays,b)-Math.max(0,a))/rangeDays*100;return `<div class="timeline-row"><div class="timeline-label"><button data-edit="${t.id}">${esc(t.title)}</button><small>${esc(t.owner)} · P${t.priority} · ${fmt(t.start)}–${fmt(t.end)}</small></div><div class="timeline-track" style="--days:${rangeDays}">${todayX>=0&&todayX<100?`<span class="today-line" style="left:${todayX}%"></span>`:''}${visible?`<button class="timeline-bar ${t.owner.toLowerCase()} ${t.dateKind.toLowerCase()}" data-bar="${t.id}" style="left:${l}%;width:${w}%" title="${esc(t.title)} · ${t.dateKind} · ${fmt(t.start)}–${fmt(t.end)}">${esc(t.owner)} · ${esc(t.title)}${b<=rangeDays?'<span class="resize-handle" title="Drag to change end date"></span>':''}</button>`:`<button data-edit="${t.id}" style="margin:17px;font-size:10px">Outside this date range ↗</button>`}</div></div>`}).join('')}${!scheduled.length?'<div class="empty">No scheduled tasks in this view. Open a task below to add dates.</div>':''}</div></div><div class="timeline-unscheduled"><h3>Unscheduled <span class="count">${unscheduled.length}</span></h3><span style="font-size:10px;color:#7a8970">Set dates when you’re ready. </span>${unscheduled.map(t=>`<button data-edit="${t.id}">${esc(t.title)} ＋</button>`).join('')}</div>`}
function renderNotes(){$('#workspace').innerHTML=`<div class="notes-grid"><section class="note-panel"><div class="note-edit-heading"><button class="eyebrow editable-note-label" data-edit-meeting title="Edit the heading and meeting notes">${esc(meeting.label)} <span>✎</span></button><button class="note-edit-button" data-edit-meeting>✎ Edit notes</button></div><h2>${esc(meeting.title)}</h2><div class="meeting-body">${meetingMarkup(meeting.body)}</div>${meeting.editedBy?`<div class="note-credit">${esc(stampText(meeting.editedBy,meeting.editedAt))}</div>`:''}</section><section class="note-panel"><span class="eyebrow">KEEP THE TEAM IN SYNC</span><h2>Notes that move with the work.</h2><p>Capture decisions, update next steps and keep this workspace current.</p><p>Use <b>Editing as</b> to credit changes. The edit trail lives in History, with a small credit on each edited task.</p><button data-open-history class="note-edit-button">◷ View edit history</button><p>Try a short focus session when you’re ready to work on the next task.</p></section></div>`}
function openMeetingEditor(){$('#notes-label').value=meeting.label;$('#notes-title').value=meeting.title;$('#notes-body').value=meeting.body;$('#notes-error').textContent='';$('#notes-editor').showModal()}
function renderHistory(){$('#history-content').innerHTML=activity.length?[...activity].reverse().map(e=>`<article class="history-entry">${avatar(e.actor)}<div><strong>${esc(e.actor)}</strong><span> · ${esc(e.message)}</span><p>${esc(e.targets.map(t=>t.title).join(' · ')||'Workspace')}</p><time>${esc(new Date(e.at).toLocaleString('en-AU',{timeZone:'Australia/Sydney'}))}</time></div></article>`).join(''):'<p class="history-empty">Edits will appear here as you work. Choose your name in “Editing as” to credit your changes.</p>';$('#history-dialog').showModal()}
function openEditor(id,defaults={}){editing=id||null;const t=tasks.find(t=>t.id===id)||{title:'',project:$('#project-filter').value||'VP teaching kit',owner:$('#owner-filter').value||'Unassigned',priority:2,status:'To do',start:'',end:'',dateKind:'Proposed',next:'',notes:'',checklist:[],review:false,dependency:'',source:'Created in this workspace.',...defaults};const f=$('#task-form');f.reset();$('#task-ref').textContent=id||'NEW TASK';$('#editor-heading').textContent=id?'A clear next step.':'Make the next step clear.';$('#project-options').innerHTML=[...new Set(tasks.map(t=>t.project))].map(p=>`<option value="${esc(p)}">`).join('');f.elements.dependency.innerHTML='<option value="">No dependency</option>'+tasks.filter(x=>x.id!==id).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('');for(const name of ['title','project','owner','priority','status','start','end','dateKind','next','notes','dependency'])f.elements[name].value=t[name];f.elements.review.checked=t.review;f.elements.checklist.value=t.checklist.map(c=>(c.done?'[x] ':'')+c.text).join('\n');$('#source-note').textContent=t.source;$('#delete-task').hidden=!id;$('#form-error').textContent='';$('#editor').showModal();}
$('#task-form').addEventListener('submit',e=>{e.preventDefault();const f=e.currentTarget,existing=tasks.find(t=>t.id===editing);const t={...(existing||{id:'VP-'+crypto.randomUUID(),source:'Created in this workspace.'})};for(const name of ['title','project','owner','status','start','end','dateKind','next','notes','dependency'])t[name]=f.elements[name].value.trim();t.priority=+f.elements.priority.value;t.review=f.elements.review.checked;t.checklist=f.elements.checklist.value.split('\n').map(x=>x.trim()).filter(Boolean).map(x=>({text:x.replace(/^\[x\]\s*/i,''),done:/^\[x\]/i.test(x)}));const draft=tasks.filter(x=>x.id!==editing).concat(t);try{validate(draft);if((t.start&&!t.end)||(!t.start&&t.end))throw Error('Set both start and end dates, or leave both blank.');}catch(err){$('#form-error').textContent=err.message;return}commit(()=>{if(editing)tasks[tasks.findIndex(x=>x.id===editing)]=t;else tasks.push(t)},'Task saved');$('#editor').close()});
$('#new-task').onclick=()=>openEditor();$('#close-editor').onclick=$('#cancel-editor').onclick=()=>$('#editor').close();$('#delete-task').onclick=()=>{const t=tasks.find(t=>t.id===editing);if(confirm(`Delete “${t.title}”? You can undo this.`)){commit(()=>{tasks=tasks.filter(x=>x.id!==editing);tasks.forEach(x=>{if(x.dependency===editing)x.dependency=''})},'Task deleted · Undo is available');$('#editor').close()}};
function setView(v){view=v;render()}
$$('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#team-nav').onclick=e=>{const b=e.target.closest('[data-owner]');if(b){$('#owner-filter').value=b.dataset.owner;setView('board')}};
$('#search').oninput=()=>render();for(const id of ['owner-filter','project-filter','priority-filter','group'])$('#'+id).onchange=render;
function clearFilters(){['search','owner-filter','project-filter','priority-filter'].forEach(id=>$('#'+id).value='')}
$('#clear').onclick=()=>{clearFilters();render()};$('#focus-kit').onclick=()=>{clearFilters();$('#project-filter').value='VP teaching kit';setView('board')};$('#undo').onclick=()=>{if(undoStack.length){const previous=undoStack.pop(),before=snapshot();tasks=previous.tasks;meeting=previous.meeting;logChanges(before,'Last change undone');persist();render();toast('Last change undone')}};
$('#help').onclick=$('#notice-help').onclick=()=>$('#info').showModal();$('#close-info').onclick=()=>$('#info').close();
$('#workspace').addEventListener('click',e=>{if(suppressClick)return;if(e.target.closest('[data-open-history]'))return renderHistory();if(e.target.closest('[data-edit-meeting]'))return openMeetingEditor();const range=e.target.closest('[data-range]');if(range){const r=range.dataset.range;rangeStart=r==='today'?addDays(today(),-3):addDays(rangeStart,r==='next'?rangeDays:-rangeDays);render();return}const add=e.target.closest('[data-add]');if(add){const group=$('#group').value;openEditor(null,{[group]:group==='priority'?+add.dataset.add:add.dataset.add});return}const edit=e.target.closest('[data-edit]');if(edit)return openEditor(edit.dataset.edit);const bar=e.target.closest('[data-bar]');if(bar)return openEditor(bar.dataset.bar);const c=e.target.closest('.card');if(c)openEditor(c.dataset.id)});
$('#workspace').addEventListener('keydown',e=>{const c=e.target.closest('.card');if(c&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openEditor(c.dataset.id)}});
$('#workspace').addEventListener('change',e=>{if(e.target.id==='zoom'){rangeDays=+e.target.value;render()}});
$('#workspace').addEventListener('dragstart',e=>{const c=e.target.closest('.card');if(!c)return;dragged=c.dataset.id;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move';c.classList.add('dragging')});
$('#workspace').addEventListener('dragover',e=>{const col=e.target.closest('.column');if(!col||!dragged)return;e.preventDefault();$$('.drop-over,.drop-before').forEach(x=>x.classList.remove('drop-over','drop-before'));col.classList.add('drop-over');const c=e.target.closest('.card');if(c&&c.dataset.id!==dragged)c.classList.add('drop-before')});
$('#workspace').addEventListener('drop',e=>{const col=e.target.closest('.column');if(!col||!dragged)return;e.preventDefault();const id=dragged,group=col.dataset.group,val=group==='priority'?+col.dataset.value:col.dataset.value,target=e.target.closest('.card')?.dataset.id;commit(()=>{const i=tasks.findIndex(t=>t.id===id),[t]=tasks.splice(i,1);t[group]=val;const at=tasks.findIndex(x=>x.id===target);tasks.splice(at<0?tasks.length:at,0,t)},'Task moved',id);dragged=null});
$('#workspace').addEventListener('dragend',()=>{dragged=null;$$('.dragging,.drop-over,.drop-before').forEach(x=>x.classList.remove('dragging','drop-over','drop-before'))});
let pointer=null,suppressClick=false;
$('#workspace').addEventListener('pointerdown',e=>{const bar=e.target.closest('[data-bar]');if(!bar||e.button!==0)return;const t=tasks.find(t=>t.id===bar.dataset.bar);pointer={id:t.id,x:e.clientX,width:bar.parentElement.getBoundingClientRect().width,resize:!!e.target.closest('.resize-handle'),bar,start:t.start,end:t.end,delta:0};bar.setPointerCapture(e.pointerId)});
$('#workspace').addEventListener('pointermove',e=>{if(!pointer)return;const delta=Math.round((e.clientX-pointer.x)/pointer.width*rangeDays);pointer.delta=pointer.resize?Math.max(-daysBetween(pointer.start,pointer.end),delta):delta;const start=pointer.resize?pointer.start:addDays(pointer.start,pointer.delta),end=addDays(pointer.end,pointer.delta),left=Math.max(0,daysBetween(rangeStart,start)),right=Math.min(rangeDays,daysBetween(rangeStart,end)+1);pointer.bar.style.left=left/rangeDays*100+'%';pointer.bar.style.width=Math.max(0,right-left)/rangeDays*100+'%';pointer.bar.title=fmt(start)+' – '+fmt(end)});
$('#workspace').addEventListener('pointerup',()=>{if(!pointer)return;const p=pointer;pointer=null;if(p.delta){suppressClick=true;setTimeout(()=>suppressClick=false,200);const nextStart=p.resize?p.start:addDays(p.start,p.delta),nextEnd=addDays(p.end,p.delta);if(!validDate(nextStart)||!validDate(nextEnd)){render();return toast('Keep dates between 2020 and 2100.')}commit(()=>{const t=tasks.find(t=>t.id===p.id);t.start=nextStart;t.end=nextEnd;t.dateKind='Proposed'},'Dates moved · marked as proposed')}});
$('#workspace').addEventListener('pointercancel',()=>{pointer=null;render()});
$('#backup').onclick=()=>{const b=new Blob([JSON.stringify({...workspaceData(),exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='volume-backup-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')};
$('#restore').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5e6)throw Error('Backup is too large (maximum 5 MB).');const data=JSON.parse(await file.text());if(data.version!==1)throw Error('This backup version is not supported.');const incoming=validate(data.tasks),incomingMeeting=data.meeting===undefined?structuredClone(defaultMeeting):validateMeeting(data.meeting),incomingActivity=data.activity===undefined?[]:validateActivity(data.activity);if(confirm(`Replace this browser’s ${tasks.length} tasks with ${incoming.length} tasks from this backup? Export first if you need a separate copy. Undo will be available.`))commit(()=>{tasks=structuredClone(incoming);meeting=structuredClone(incomingMeeting);activity=structuredClone(incomingActivity)},'Backup imported')}catch(err){alert('Could not import: '+err.message)}e.target.value=''};
window.addEventListener('storage',e=>{if(e.key===storageKey())toast('This workspace changed in another tab. Export any unsaved work, then reload to see those changes.')});

$('#workspace-menu').onclick=()=>{renderSpaces();$('#workspace-dialog').showModal()};$('#close-spaces').onclick=()=>$('#workspace-dialog').close();
$('#workspace-list').onclick=e=>{const b=e.target.closest('[data-switch-workspace]');if(b){switchWorkspace(b.dataset.switchWorkspace);$('#workspace-dialog').close()}};
$('#rename-workspace').onclick=()=>{const name=$('#workspace-name-input').value.trim();if(!name)return;workspaces.find(w=>w.id===workspaceId).name=name;saveRegistry();renderSpaces();render();toast('Workspace renamed')};
$('#new-workspace-form').addEventListener('submit',e=>{e.preventDefault();const name=$('#new-workspace-name').value.trim();if(!name||workspaces.length>=50)return;const id=crypto.randomUUID(),copy=$('#copy-workspace').checked;const data={version:1,tasks:copy?structuredClone(tasks):[],meeting:copy?structuredClone(meeting):freshMeeting(),activity:[]};try{localStorage.setItem(storageKey(id),JSON.stringify(data));workspaces.push({id,name});if(!saveRegistry())throw Error('Could not save workspace settings.');switchWorkspace(id);$('#new-workspace-name').value='';$('#copy-workspace').checked=false;$('#workspace-dialog').close();toast('New workspace created')}catch(err){toast(err.message)}});
$('#editing-as').onchange=e=>{actor=e.target.value;try{localStorage.setItem(KEY+'-actor',actor)}catch(err){toast('Your editor name is set for this visit. Browser storage is unavailable.')}};
$('#history-button').onclick=renderHistory;$('#close-history').onclick=()=>$('#history-dialog').close();
$('#close-notes').onclick=$('#cancel-notes').onclick=()=>$('#notes-editor').close();
$('#notes-form').addEventListener('submit',e=>{e.preventDefault();const next={...meeting,label:$('#notes-label').value.trim(),title:$('#notes-title').value.trim(),body:$('#notes-body').value};try{validateMeeting(next)}catch(err){$('#notes-error').textContent=err.message;return}if(next.label!==meeting.label||next.title!==meeting.title||next.body!==meeting.body)commit(()=>{meeting=next},'Meeting notes updated');$('#notes-editor').close()});
renderSpaces();render();if(startupWarning){toast(startupWarning);$('#save-state').title=startupWarning;}
